178	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
179	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
180	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
